import type { ReactNode } from 'react'

/**
 * Maps a generated file's path to how its card presents it: the language's real
 * brand logo, a short type badge, the human name, and a highlight.js language for
 * the code body. This is what makes a file card show "the original logo of the
 * language" (e.g. the Python mark on `app.py`, the HTML5 shield on `index.html`).
 *
 * Provenance: the brand marks are single 24×24 paths lifted verbatim from
 * simple-icons (CC0), drawn with `fill="currentColor"` — the same inline-SVG,
 * zero-dependency approach as the site's `modelBrands.ts` and the app's other
 * icons. simple-icons has no mark for SQL/plain text, so those (and any unknown
 * extension) fall back to a neutral document glyph. Marks that are monochrome in
 * simple-icons (JSON, Markdown, Rust, Java/OpenJDK) carry no `color`, so they
 * inherit the card's text colour and stay legible on both themes.
 */
export interface FileType {
  /** Human name, e.g. "Python", "HTML". */
  name: string
  /** Short uppercase label shown as the type badge (where the reference card said "ZIP"). */
  badge: string
  /** highlight.js language id for the code body; '' lets it stay unhighlighted. */
  hljs: string
  /** Brand colour for the logo; omitted for monochrome marks so they inherit currentColor. */
  color?: string
  /** 24×24 icon path, drawn with `fill="currentColor"`. */
  path: string
}

