/** Neutral document glyph for SQL, plain text, and any unmapped extension. */
const GENERIC =
  'M13.5 1H5.5A1.5 1.5 0 0 0 4 2.5v19A1.5 1.5 0 0 0 5.5 23h13a1.5 1.5 0 0 0 1.5-1.5V7.5z'

const GENERIC_TYPE: Omit<FileType, 'name' | 'badge'> = { hljs: '', path: GENERIC }

/** Extension → presentation. Several extensions share one language's mark. */
const BY_EXT: Record<string, FileType> = {
  html: { name: 'HTML', badge: 'HTML', hljs: 'html', color: '#E34F26', path: HTML5 },
  htm: { name: 'HTML', badge: 'HTML', hljs: 'html', color: '#E34F26', path: HTML5 },
  css: { name: 'CSS', badge: 'CSS', hljs: 'css', color: '#1572B6', path: CSS3 },
  scss: { name: 'SCSS', badge: 'SCSS', hljs: 'scss', color: '#1572B6', path: CSS3 },
  js: { name: 'JavaScript', badge: 'JS', hljs: 'javascript', color: '#F7DF1E', path: JAVASCRIPT },
  mjs: { name: 'JavaScript', badge: 'JS', hljs: 'javascript', color: '#F7DF1E', path: JAVASCRIPT },
  cjs: { name: 'JavaScript', badge: 'JS', hljs: 'javascript', color: '#F7DF1E', path: JAVASCRIPT },
  jsx: { name: 'React (JSX)', badge: 'JSX', hljs: 'javascript', color: '#61DAFB', path: REACT },
  ts: { name: 'TypeScript', badge: 'TS', hljs: 'typescript', color: '#3178C6', path: TYPESCRIPT },
  tsx: { name: 'React (TSX)', badge: 'TSX', hljs: 'typescript', color: '#61DAFB', path: REACT },
  py: { name: 'Python', badge: 'PY', hljs: 'python', color: '#3776AB', path: PYTHON },
  json: { name: 'JSON', badge: 'JSON', hljs: 'json', path: JSON_MARK },
  md: { name: 'Markdown', badge: 'MD', hljs: 'markdown', path: MARKDOWN },
  markdown: { name: 'Markdown', badge: 'MD', hljs: 'markdown', path: MARKDOWN },
  sh: { name: 'Shell', badge: 'SH', hljs: 'bash', color: '#4EAA25', path: BASH },
  bash: { name: 'Shell', badge: 'SH', hljs: 'bash', color: '#4EAA25', path: BASH },
  yml: { name: 'YAML', badge: 'YAML', hljs: 'yaml', color: '#CB171E', path: YAML },
  yaml: { name: 'YAML', badge: 'YAML', hljs: 'yaml', color: '#CB171E', path: YAML },
  go: { name: 'Go', badge: 'GO', hljs: 'go', color: '#00ADD8', path: GO },
  rs: { name: 'Rust', badge: 'RS', hljs: 'rust', path: RUST },
  rb: { name: 'Ruby', badge: 'RB', hljs: 'ruby', color: '#CC342D', path: RUBY },
  php: { name: 'PHP', badge: 'PHP', hljs: 'php', color: '#777BB4', path: PHP },
  java: { name: 'Java', badge: 'JAVA', hljs: 'java', path: JAVA },
  sql: { name: 'SQL', badge: 'SQL', hljs: 'sql', path: GENERIC },
  txt: { name: 'Text', badge: 'TXT', ...GENERIC_TYPE },
  text: { name: 'Text', badge: 'TXT', ...GENERIC_TYPE }
}

/** Look up how to present a file at `filePath`; unknown extensions get a neutral glyph. */
export function fileTypeFor(filePath: string): FileType {
  const base = filePath.replace(/\\/g, '/').split('/').pop() ?? filePath
  const dot = base.lastIndexOf('.')
  const ext = dot > 0 ? base.slice(dot + 1).toLowerCase() : ''
  const known = BY_EXT[ext]
  if (known) return known
  return { name: ext ? ext.toUpperCase() : 'File', badge: ext ? ext.toUpperCase() : 'FILE', ...GENERIC_TYPE }
}

/**
 * The language brand logo for `path`, coloured with its brand hue (or the current
 * text colour for monochrome marks). `size` is the square px edge (default 16).
 */
export function FileIcon({ path, size = 16 }: { path: string; size?: number }): ReactNode {
  const type = fileTypeFor(path)
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      style={type.color ? { color: type.color } : undefined}
    >
      <path d={type.path} />
    </svg>
  )
}
